'use client';

import { useCallback, useEffect, useMemo, useState } from 'react';
import type { AuthChangeEvent, Session } from '@supabase/supabase-js';
import { useRouter } from 'next/navigation';
import {
  Edit,
  Loader2,
  Phone,
  Plus,
  Search,
  ShieldCheck,
  Trash2,
  Truck,
  X,
} from 'lucide-react';
import { useDashboardAuth } from '@/components/dashboard/DashboardAuthContext';
import { apiFetch } from '@/utils/api';
import { createClient } from '@/utils/supabase/client';

interface ShippingProvider {
  id: string;
  name: string;
  contact: string | null;
  isActive: boolean;
  createdAt: string;
}

type ProviderAccess = {
  read: boolean;
  create: boolean;
  update: boolean;
  delete: boolean;
};

const defaultProviderAccess: ProviderAccess = {
  read: false,
  create: false,
  update: false,
  delete: false,
};

function normalizeProvidersPayload(payload: unknown): ShippingProvider[] {
  if (Array.isArray(payload)) {
    return payload as ShippingProvider[];
  }

  if (
    payload &&
    typeof payload === 'object' &&
    Array.isArray((payload as { data?: unknown[] }).data)
  ) {
    return (payload as { data: ShippingProvider[] }).data;
  }

  return [];
}

export default function ShippingProvidersPage() {
  const { accessToken } = useDashboardAuth();
  const router = useRouter();
  const supabase = createClient();
  const [providers, setProviders] = useState<ShippingProvider[]>([]);
  const [providerAccess, setProviderAccess] =
    useState<ProviderAccess>(defaultProviderAccess);
  const [selectedProviderId, setSelectedProviderId] = useState<string | null>(
    null,
  );
  const [loading, setLoading] = useState(true);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [search, setSearch] = useState('');
  const [formData, setFormData] = useState({
    name: '',
    contact: '',
    isActive: true,
  });

  const resolveApiErrorMessage = useCallback(
    async (
      res: Response,
      fallbackMessage: string,
      options?: { redirectOnUnauthorized?: boolean; forbiddenMessage?: string },
    ) => {
      if (res.status === 401) {
        if (options?.redirectOnUnauthorized) {
          router.push(
            `/login?redirect=${encodeURIComponent(window.location.pathname)}`,
          );
        }

        return 'Tu sesion expiro. Inicia sesion nuevamente.';
      }

      if (res.status === 403) {
        return (
          options?.forbiddenMessage ||
          'No tienes permisos para gestionar proveedores de envio.'
        );
      }

      const body = await res.json().catch(() => null);

      if (typeof body?.message === 'string' && body.message.trim()) {
        return body.message;
      }

      if (Array.isArray(body?.message)) {
        const firstMessage = body.message.find(
          (value: unknown) => typeof value === 'string' && value.trim(),
        );

        if (firstMessage) {
          return firstMessage;
        }
      }

      if (typeof body?.error === 'string' && body.error.trim()) {
        return body.error;
      }

      return fallbackMessage;
    },
    [router],
  );

  const getAuthHeaders = useCallback(async (): Promise<Record<string, string>> => {
    const {
      data: { session },
    } = await supabase.auth.getSession();

    const token = session?.access_token ?? accessToken;
    if (!token) {
      return {};
    }

    return { Authorization: `Bearer ${token}` };
  }, [accessToken, supabase.auth]);

  const fetchProviders = useCallback(async () => {
    setLoading(true);
    setError(null);

    try {
      const headers = await getAuthHeaders();
      const [providersRes, accessRes] = await Promise.all([
        apiFetch('/shipping/providers', { headers }),
        apiFetch('/shipping/providers/access', { headers }),
      ]);

      if (!providersRes.ok) {
        setProviders([]);
        setProviderAccess(defaultProviderAccess);
        setError(
          await resolveApiErrorMessage(
            providersRes,
            'No fue posible cargar los proveedores de envio.',
            {
              redirectOnUnauthorized: true,
              forbiddenMessage:
                'No tienes permisos para ver proveedores de envio.',
            },
          ),
        );
        return;
      }

      const providersBody = await providersRes.json().catch(() => []);
      setProviders(normalizeProvidersPayload(providersBody));

      if (!accessRes.ok) {
        setProviderAccess(defaultProviderAccess);
        setError(
          await resolveApiErrorMessage(
            accessRes,
            'No fue posible resolver los permisos operativos de proveedores.',
            {
              redirectOnUnauthorized: true,
              forbiddenMessage:
                'No tienes permisos para operar proveedores de envio.',
            },
          ),
        );
        return;
      }

      const accessBody = await accessRes
        .json()
        .catch(() => defaultProviderAccess);

      setProviderAccess({
        read: accessBody?.read === true,
        create: accessBody?.create === true,
        update: accessBody?.update === true,
        delete: accessBody?.delete === true,
      });
    } catch (fetchError) {
      console.error(fetchError);
      setProviders([]);
      setProviderAccess(defaultProviderAccess);
      setError('No fue posible conectar con la API de envios.');
    } finally {
      setLoading(false);
    }
  }, [getAuthHeaders, resolveApiErrorMessage]);

  useEffect(() => {
    void fetchProviders();

    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange(
      (event: AuthChangeEvent, session: Session | null) => {
        if (!(session?.access_token ?? accessToken)) {
          setProviders([]);
          setProviderAccess(defaultProviderAccess);
          setLoading(false);
          return;
        }

        if (
          event === 'SIGNED_IN' ||
          event === 'TOKEN_REFRESHED' ||
          event === 'USER_UPDATED'
        ) {
          void fetchProviders();
        }
      },
    );

    return () => {
      subscription.unsubscribe();
    };
  }, [accessToken, fetchProviders, supabase.auth]);

  const filteredProviders = useMemo(() => {
    const query = search.trim().toLowerCase();
    if (!query) return providers;

    return providers.filter((provider) =>
      [provider.name, provider.contact || '', provider.id].some((value) =>
        value.toLowerCase().includes(query),
      ),
    );
  }, [providers, search]);

  const handleCreateOrUpdateProvider = async (event: React.FormEvent) => {
    event.preventDefault();
    const isEditing = Boolean(selectedProviderId);

    if (isEditing ? !providerAccess.update : !providerAccess.create) {
      setError(
        isEditing
          ? 'No tienes permisos para editar proveedores de envio.'
          : 'No tienes permisos para crear proveedores de envio.',
      );
      return;
    }

    setSubmitting(true);
    setError(null);

    try {
      const headers = await getAuthHeaders();
      const res = await apiFetch(
        isEditing
          ? `/shipping/providers/${selectedProviderId}`
          : '/shipping/providers',
        {
          method: isEditing ? 'PATCH' : 'POST',
          headers: {
            'Content-Type': 'application/json',
            ...headers,
          },
          body: JSON.stringify(formData),
        },
      );

      if (res.ok) {
        setIsModalOpen(false);
        setSelectedProviderId(null);
        setFormData({ name: '', contact: '', isActive: true });
        await fetchProviders();
        return;
      }

      setError(
        await resolveApiErrorMessage(
          res,
          `No fue posible ${isEditing ? 'actualizar' : 'guardar'} el proveedor.`,
          {
            redirectOnUnauthorized: true,
            forbiddenMessage: isEditing
              ? 'No tienes permisos para editar proveedores de envio.'
              : 'No tienes permisos para crear proveedores de envio.',
          },
        ),
      );
    } catch (submitError) {
      console.error(submitError);
      setError(
        `No fue posible ${isEditing ? 'actualizar' : 'guardar'} el proveedor.`,
      );
    } finally {
      setSubmitting(false);
    }
  };

  const handleEdit = (provider: ShippingProvider) => {
    if (!providerAccess.update) {
      setError('No tienes permisos para editar proveedores de envio.');
      return;
    }

    setSelectedProviderId(provider.id);
    setFormData({
      name: provider.name,
      contact: provider.contact || '',
      isActive: provider.isActive,
    });
    setError(null);
    setIsModalOpen(true);
  };

  const handleDelete = async (id: string) => {
    if (!providerAccess.delete) {
      setError('No tienes permisos para eliminar proveedores de envio.');
      return;
    }

    if (!confirm('Estas seguro de eliminar este proveedor?')) return;

    try {
      setError(null);
      const headers = await getAuthHeaders();
      const res = await apiFetch(`/shipping/providers/${id}`, {
        method: 'DELETE',
        headers,
      });

      if (res.ok) {
        await fetchProviders();
        return;
      }

      setError(
        await resolveApiErrorMessage(
          res,
          'No fue posible eliminar el proveedor.',
          {
            redirectOnUnauthorized: true,
            forbiddenMessage:
              'No tienes permisos para eliminar proveedores de envio.',
          },
        ),
      );
    } catch (deleteError) {
      console.error(deleteError);
      setError('No fue posible eliminar el proveedor.');
    }
  };

  return (
    <div className="mx-auto max-w-7xl space-y-8 p-8 animate-in fade-in slide-in-from-bottom-4 duration-500 md:p-12">
      <div className="flex flex-col justify-between gap-6 md:flex-row md:items-center">
        <div className="space-y-1">
          <div className="flex items-center gap-3">
            <div className="rounded-xl bg-primary p-2.5 text-base-color shadow-lg shadow-primary/20">
              <Truck className="h-6 w-6" />
            </div>
            <h1 className="text-3xl font-black tracking-tight text-primary">
              Proveedores de Envio
            </h1>
          </div>
          <p className="font-medium text-muted">
            Gestiona las empresas de mensajeria y sus datos operativos.
          </p>
        </div>
        {providerAccess.create ? (
          <button
            onClick={() => {
              setSelectedProviderId(null);
              setFormData({ name: '', contact: '', isActive: true });
              setError(null);
              setIsModalOpen(true);
            }}
            className="flex items-center justify-center gap-2 rounded-xl bg-primary px-6 py-3 font-bold text-base-color shadow-lg shadow-primary/20 transition-all hover:scale-[1.02] active:scale-95"
          >
            <Plus className="h-5 w-5" />
            Nuevo Proveedor
          </button>
        ) : (
          <div className="inline-flex items-center justify-center rounded-xl border border-theme bg-base px-4 py-3 text-xs font-black uppercase tracking-widest text-muted">
            Solo lectura
          </div>
        )}
      </div>

      <div className="overflow-hidden rounded-3xl border border-theme bg-surface shadow-sm">
        <div className="border-b border-theme bg-base/30 p-6">
          <div className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
            <div className="relative md:max-w-md md:flex-1">
              <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted" />
              <input
                type="text"
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder="Buscar proveedor..."
                className="w-full rounded-xl border border-theme bg-base py-2.5 pl-10 pr-4 text-sm font-medium outline-none transition-all focus:ring-2 focus:ring-primary/20"
              />
            </div>
            {error ? (
              <p className="text-sm font-semibold text-rose-600">{error}</p>
            ) : null}
          </div>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full border-collapse text-left">
            <thead>
              <tr className="border-b border-theme bg-base/20 text-[10px] font-black uppercase tracking-widest text-muted/60">
                <th className="px-8 py-4">Nombre / Empresa</th>
                <th className="px-8 py-4">Contacto</th>
                <th className="px-8 py-4">Estado</th>
                <th className="px-8 py-4 text-right">Acciones</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-theme">
              {loading ? (
                <tr>
                  <td colSpan={4} className="px-8 py-12 text-center">
                    <Loader2 className="mx-auto h-8 w-8 animate-spin text-primary" />
                  </td>
                </tr>
              ) : filteredProviders.length === 0 ? (
                <tr>
                  <td
                    colSpan={4}
                    className="px-8 py-12 text-center font-medium text-muted"
                  >
                    {providers.length === 0
                      ? 'No hay proveedores registrados.'
                      : 'No hay resultados para la busqueda actual.'}
                  </td>
                </tr>
              ) : (
                filteredProviders.map((provider) => (
                  <tr
                    key={provider.id}
                    className="group transition-all hover:bg-primary/5"
                  >
                    <td className="px-8 py-5">
                      <div className="flex flex-col">
                        <span className="font-bold text-primary">
                          {provider.name}
                        </span>
                        <span className="text-[10px] font-black uppercase tracking-widest text-muted">
                          ID: {provider.id.split('-')[0]}
                        </span>
                      </div>
                    </td>
                    <td className="px-8 py-5 text-sm font-medium text-muted">
                      <div className="flex items-center gap-2">
                        <Phone className="h-3 w-3" />
                        {provider.contact || 'No asignado'}
                      </div>
                    </td>
                    <td className="px-8 py-5">
                      <span
                        className={`rounded-full border px-3 py-1 text-[10px] font-black uppercase tracking-widest ${
                          provider.isActive
                            ? 'border-emerald-100 bg-emerald-50 text-emerald-600'
                            : 'border-rose-100 bg-rose-50 text-rose-600'
                        }`}
                      >
                        {provider.isActive ? 'Activo' : 'Inactivo'}
                      </span>
                    </td>
                    <td className="px-8 py-5 text-right">
                      {providerAccess.update || providerAccess.delete ? (
                        <div className="flex justify-end gap-2">
                          {providerAccess.update ? (
                            <button
                              onClick={() => handleEdit(provider)}
                              className="rounded-lg border border-theme bg-base p-2 transition-all hover:bg-primary hover:text-base-color"
                            >
                              <Edit className="h-4 w-4" />
                            </button>
                          ) : null}
                          {providerAccess.delete ? (
                            <button
                              onClick={() => handleDelete(provider.id)}
                              className="rounded-lg border border-theme bg-base p-2 text-rose-500 transition-all hover:bg-rose-500 hover:text-white"
                            >
                              <Trash2 className="h-4 w-4" />
                            </button>
                          ) : null}
                        </div>
                      ) : (
                        <span className="text-[10px] font-black uppercase tracking-widest text-muted">
                          Solo lectura
                        </span>
                      )}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {isModalOpen ? (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
          <div
            className="absolute inset-0 bg-primary/20 backdrop-blur-sm"
            onClick={() => setIsModalOpen(false)}
          />
          <div className="relative w-full max-w-lg overflow-hidden rounded-3xl border border-theme bg-surface shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="relative border-b border-theme bg-primary p-8 text-base-color">
              <h2 className="text-2xl font-black">
                {selectedProviderId ? 'Editar Proveedor' : 'Nuevo Proveedor'}
              </h2>
              <p className="text-sm font-medium text-base-color/60">
                Configura una empresa de mensajeria logistica.
              </p>
            </div>
            <button
              type="button"
              onClick={() => setIsModalOpen(false)}
              className="absolute right-6 top-6 rounded-xl p-2 transition-colors hover:bg-white/10"
              aria-label="Cerrar modal"
            >
              <X className="h-5 w-5" />
            </button>
            <form
              onSubmit={handleCreateOrUpdateProvider}
              className="space-y-4 p-8"
            >
              <div className="grid grid-cols-1 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black uppercase text-muted">
                    Nombre de la Empresa
                  </label>
                  <input
                    required
                    value={formData.name}
                    onChange={(event) =>
                      setFormData({ ...formData, name: event.target.value })
                    }
                    placeholder="Ej: Servientrega, Interrapidisimo"
                    className="w-full rounded-xl border border-theme bg-base px-4 py-3 text-sm font-bold outline-none focus:ring-2 focus:ring-primary/20"
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black uppercase text-muted">
                    Contacto / Telefono
                  </label>
                  <input
                    value={formData.contact}
                    onChange={(event) =>
                      setFormData({ ...formData, contact: event.target.value })
                    }
                    className="w-full rounded-xl border border-theme bg-base px-4 py-3 text-sm font-bold outline-none focus:ring-2 focus:ring-primary/20"
                  />
                </div>
                <div className="flex items-center gap-3 pt-2">
                  <input
                    type="checkbox"
                    id="isActive"
                    checked={formData.isActive}
                    onChange={(event) =>
                      setFormData({
                        ...formData,
                        isActive: event.target.checked,
                      })
                    }
                    className="h-5 w-5 rounded-lg border-theme text-primary focus:ring-primary/20"
                  />
                  <label
                    htmlFor="isActive"
                    className="text-xs font-bold text-primary"
                  >
                    Este proveedor esta activo para nuevos envios
                  </label>
                </div>
              </div>
              {error ? (
                <p className="text-sm font-semibold text-rose-600">{error}</p>
              ) : null}
              <div className="flex gap-4 pt-4">
                <button
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="flex-1 rounded-2xl border border-theme bg-base px-6 py-4 font-bold text-muted"
                >
                  Cancelar
                </button>
                <button
                  disabled={submitting}
                  className="flex-[2] rounded-2xl bg-primary px-6 py-4 font-black text-base-color shadow-lg shadow-primary/20 transition-transform active:scale-95"
                >
                  <span className="flex items-center justify-center gap-2">
                    {submitting ? (
                      <Loader2 className="h-4 w-4 animate-spin" />
                    ) : (
                      <ShieldCheck className="h-4 w-4" />
                    )}
                    {selectedProviderId ? 'Actualizar' : 'Guardar'} Proveedor
                  </span>
                </button>
              </div>
            </form>
          </div>
        </div>
      ) : null}
    </div>
  );
}
